import { OWNER_NAME,updatePlan,DEFAULT_PROFILE,dateIST,timeIST,ACTIVITY_KINDS,activityFields,measurementKind,measurementFields,entryData,addDays,dayDiff,planFor,totals,workoutDone,analyze,trend,calorieEstimate,compositionProjection,validateRecord } from './domain.js';
import { DataStore,uuid,queueChange } from './store.js';

const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=0)=>Number(v).toLocaleString('en-IN',{maximumFractionDigits:d});
const paths={
  home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
  food:'M5 3v7m3-7v7m-6-7v7c0 3 6 3 6 0m-3 3v8M19 3c-4 2-5 7-3 10h3m0-10v18',
  activity:'M3 12h4l3-8 4 16 3-8h4',
  chart:'M4 4v16h17M8 15l4-5 4 2 4-7',
  plan:'M8 3H5a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V4a1 1 0 0 0-1-1h-3M9 2h6v4H9ZM8 11h8M8 15h8',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M10 3h4l1 3 3 1 3-1 2 4-2 2v3l1 2-3 3-3-1-3 1-1 2h-4l-1-3-3-1-2 1-3-4 2-2v-3l-1-2 3-3 3 1Z',
  water:'M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12ZM8 15a4 4 0 0 0 4 4',
  flame:'M12 3c1 5 6 6 6 11a6 6 0 0 1-12 0c0-3 2-5 3-6 0 3 2 4 3 4 2-3 1-6 0-9Z',
  protein:'M4 9h3v6H4zM17 9h3v6h-3zM2 10v4m20-4v4M7 12h10',
  walk:'M13 4a1 1 0 1 0 0 .1M9 20l2-6m3 6-1-7-3-3 2-4 3 4 4 1M5 12l4-2',
  check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',
  clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',leaf:'M20 3C5 1 1 11 8 17S23 12 20 3ZM5 21 16 10',
  edit:'m15 5 4 4M4 20l4-1L20 7a2 2 0 0 0-4-4L4 15Z',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',
  close:'m6 6 12 12M6 18 18 6',sync:'M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5',
  cloud:'M7 18a5 5 0 1 1-1-10 7 7 0 0 1 13 2 4 4 0 0 1-1 8ZM9 14l2 2 4-4',
  weight:'M5 4h14a2 2 0 0 1 2 2v13a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2ZM8 8a6 6 0 0 1 8 0l-4 5Z',
  download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-5',
  cup:'M6 5h12l-2 16H8ZM5 2h14M7 12h10',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 11v6m0-10v1',
  heart:'M12 20 4 12C-2 5 8-1 12 6c4-7 14-1 8 6Z',logout:'M10 4H4v16h6M10 12h11m-5-5 5 5-5 5'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.activity}"/></svg>`;
const button=(label,action,cls='',ico='')=>`<button class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const empty=(title,detail,action='',label='Add entry',ico='leaf')=>`<div class="empty">${icon(ico)}<strong>${title}</strong><p>${detail}</p>${action?button(label,action):''}</div>`;
let store,session,view='today',selectedDate=dateIST(),range=7,installPrompt,updateWaiting,toastTimer;
let currentForm=null;
const records=()=>Object.values(store?.state.records||{}).filter(r=>!r.deleted);
const profile=()=>({...DEFAULT_PROFILE,...store?.state.records.profile?.data,name:OWNER_NAME});
const hasProfile=()=>!!store?.state.records.profile&&!store.state.records.profile.deleted;
const friendly=(date,short=false)=>new Date(`${date}T12:00:00Z`).toLocaleDateString('en-IN',{weekday:short?'short':'long',day:'numeric',month:short?'short':'long'});
const dayNames=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const initial=()=>profile().name?.split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase()||'GB';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function statusHTML(){
  const count=store?.state.queue.length||0;
  const status=store?.status||'connecting';
  const states={saved:['cloud','All changes saved',''],pending:['sync',`${count} changes pending`,'warn'],syncing:['sync','Syncing…','neutral'],offline:['cloud',`${count} pending · Offline`,'warn'],error:['cloud',`${count} pending · Reconnect`,'warn'],attention:['info','Review sync conflicts','bad'],connecting:['sync','Connecting…','neutral']};
  const [ico,label,cls]=states[status]||states.connecting;
  return `<button class="sync-button" data-action="sync-details" aria-label="${escape(label)}"><span class="pill ${cls}"><span class="dot"></span>${label}</span></button>`;
}
function shell(){
  const p=profile(), titles={today:'Overview',food:'Food & water',activity:'Movement',progress:'Your progress',plan:'Your plan',settings:'Settings'};
  const nav=[['today','home','Today'],['food','food','Food & water'],['activity','activity','Movement'],['progress','chart','Progress'],['plan','plan','My plan']];
  $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-mark">g<span>•</span></div><span>gym buddy</span></div><div class="nav-container"><div class="nav-label eyebrow">Your space</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,i,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav></div><div class="sidebar-bottom"><div class="small-promo">${icon('leaf')}<div class="mt"><strong>Small steps. Real change.</strong><p>Your only competition is where you were yesterday.</p><button class="text-button" data-view="plan">See your plan ${icon('arrow')}</button></div></div><nav class="nav"><button data-view="settings" class="${view==='settings'?'active':''}">${icon('settings')}<span>Settings & data</span></button></nav><button class="profile-button" data-view="settings"><div class="avatar">${escape(initial())}</div><div><div class="name">${escape(p.name||'Your profile')}</div><div class="muted small">Your personal journey</div></div>${icon('right')}</button></div></aside><div class="workspace"><header class="topbar"><div class="mobile-brand"><div class="brand-mark">g<span>•</span></div>gym buddy</div><div class="breadcrumb">My workspace <span class="muted"> / </span><strong>${titles[view]}</strong></div><div class="spacer"></div><div id="sync-status">${statusHTML()}</div><span class="top-divider"></span><span class="eyebrow">IST · UTC+5:30</span><button class="profile-button" data-view="settings" aria-label="Open settings"><span class="avatar top-avatar">${escape(initial())}</span></button></header><main id="main" class="main" tabindex="-1">${mainView()}</main></div></div>`;
}
function heading(title,subtitle,dates=false,action='quick',label='Log something'){
  return `<div class="page-title"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="date-control">${dates?`<button class="icon-button" data-action="previous-day" aria-label="Previous day">${icon('left')}</button><button class="icon-button" data-action="next-day" aria-label="Next day" ${selectedDate>=dateIST()?'disabled':''}>${icon('right')}</button><input id="selected-date" type="date" aria-label="Log date in IST" value="${selectedDate}" max="${dateIST()}">`:''}${action?button(label,action,'primary','plus'):''}</div></div>`;
}
function mainView(){
  const content={today:todayView,food:foodView,activity:activityView,progress:progressView,plan:planView,settings:settingsView};
  return `${session?.local?'<div class="banner"><span>Local development · Your data is in a local database. Cloud sync to your account is not connected.</span></div>':''}${store?.error?`<div class="banner"><span>${escape(store.error)}</span><button class="text-button" data-action="sync">Retry</button></div>`:''}${updateWaiting?'<div class="banner"><span>An app update is ready. Pending entries stay on this device.</span><button class="text-button" data-action="update-app">Update</button></div>':''}${!hasProfile()?`<div class="banner"><span>Your private DEXA baseline has not synced yet. Reconnect to load your profile.</span><button class="text-button" data-action="sync">Retry sync</button></div>`:''}${content[view]()}<footer class="bottom-caption"><span>One day at a time. You’re building something good.</span><span>${icon('shield')} Private records · IST dates · ${store?.state.lastSync?`Last sync ${new Date(store.state.lastSync).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit'})} IST`:'Not synced yet'}</span></footer>`;
}
function metric(label,value,unit,target,percent,ico,color){return `<article class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${color}">${icon(ico)}</span></div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-target">${target}</div><div class="progress-bar ${color}"><span style="width:${Math.max(0,Math.min(100,percent||0))}%"></span></div></article>`;}
function metricsHTML(){const p=profile(),t=totals(records(),selectedDate),plan=planFor(selectedDate,p);return `<div class="metrics">${metric('Energy logged',t.meals.length?n(t.calories):'—','kcal',p.calorieTarget?`of ${n(p.calorieTarget)} kcal target`:'Set an optional calorie target',p.calorieTarget?t.calories/p.calorieTarget*100:0,'flame','orange')}${metric('Protein',t.meals.length?n(t.protein,1):'—','g',`of ${n(p.proteinTarget)} g target`,t.protein/p.proteinTarget*100,'protein','')}${metric('Water',t.water?n(t.water):'—','ml',`of ${n(p.waterTarget)} ml target`,t.water/p.waterTarget*100,'water','blue')}${metric('Movement',t.activities.length?n(t.minutes):'—','min',plan.minutes?`${plan.minutes} min ${plan.type==='Strength'?'strength':'walking'} planned`:plan.type==='Preparation'?'Your plan starts soon':'Recovery day · Move comfortably',plan.minutes?t.minutes/plan.minutes*100:0,'walk','pink')}</div>`;}
const runnerArt=()=>`<svg class="hero-art" viewBox="0 0 230 180" fill="none" aria-hidden="true"><ellipse cx="125" cy="165" rx="95" ry="6" fill="#173b2b"/><path d="M33 143h149l20 13H18z" fill="#82a17a"/><path d="m183 143-12-91h-29m30 0h27" stroke="#b9cda5" stroke-width="6" stroke-linecap="round"/><path d="m125 86 14 21-12 32m-7-48-20 28-29 8m47-69-13 21 17 17m-12-25-16 11-16-3m39-17 17 12 18-4" stroke="#e0edbc" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/><circle cx="127" cy="37" r="10" fill="#e0edbc"/><path d="m64 143 14-4m44 4h15" stroke="#e0edbc" stroke-width="7" stroke-linecap="round"/><path d="M35 55h30M26 70h32M37 85h17" stroke="#ffffff18" stroke-width="2" stroke-linecap="round"/></svg>`;
function heroHTML(){const p=profile(),plan=planFor(selectedDate,p),prep=plan.type==='Preparation';const sessionPlan=prep?planFor(p.startDate,p):plan;return `<section class="hero"><div><div class="eyebrow">${prep?'Your next chapter starts here':`Week ${plan.week} · ${plan.type==='Recovery'?'Make room for recovery':'A little stronger, every day'}`}</div><h2>${prep?'A fresh start.<br>A stronger you.':escape(plan.title)}</h2><p>${prep?`Your beginner plan begins ${friendly(p.startDate,true)}. Start gently, find your rhythm, and build from there.`:escape(plan.detail)}</p>${button(prep?'Explore your plan':plan.type==='Recovery'?'Check in for today':'Log your session',prep?'view-plan':plan.type==='Recovery'?'checkin':'add-activity','lime','arrow')}</div><div class="hero-time">${icon('clock')} ${escape(p.workoutTime)} IST</div>${runnerArt()}</section>`;}
function todayView(){const p=profile(),t=totals(records(),selectedDate),plan=planFor(selectedDate,p),done=plan.type==='Preparation'?hasProfile():workoutDone(plan,t);const checks=[{done,title:plan.type==='Preparation'?'Your November plan is ready':plan.title,detail:plan.type==='Preparation'?'DEXA baseline loaded · Review your schedule anytime':plan.type==='Recovery'?'Rest is part of the plan':`${p.workoutTime} IST · ${plan.minutes} minutes`,action:plan.type==='Preparation'?'profile':plan.type==='Recovery'?'checkin':'add-activity',label:done?'View':'Log'},{done:t.water>=p.waterTarget,title:'Keep your water close',detail:`${n(t.water)} of ${n(p.waterTarget)} ml logged`,action:'add-water',label:'Add'},{done:t.protein>=p.proteinTarget,title:'Make room for protein',detail:`${n(t.protein,1)} of ${n(p.proteinTarget)} g logged`,action:'add-meal',label:'Log'},{done:!!t.checkin.foodComplete,title:'Finish your daily check-in',detail:t.checkin.foodComplete?'Food log marked complete':'Confirm your food log, steps and recovery',action:'checkin',label:t.checkin.foodComplete?'Edit':'Check in'}];return `${heading(`Your day, ${escape(p.name?.split(' ')[0]||'your way')}.`,`${friendly(selectedDate)} · A little progress adds up.`,true)}${heroHTML()}<div class="row between section-label"><span>Your daily rhythm</span><span class="muted tiny">${selectedDate===dateIST()?'Today':friendly(selectedDate,true)} · Based on your entries</span></div>${metricsHTML()}<div class="today-grid"><section class="panel"><div class="panel-head"><h2>A plan you can follow</h2><span class="pill neutral">${checks.filter(c=>c.done).length} / 4 done</span></div><div class="checklist">${checks.map(c=>`<div class="check-row"><span class="check-icon ${c.done?'done':''}">${icon(c.done?'check':'clock')}</span><div class="spacer"><h3>${c.title}</h3><p>${c.detail}</p></div><button class="text-button" data-action="${c.action}">${c.label} ${icon('right')}</button></div>`).join('')}</div></section>${waterPanel()}<section class="panel"><div class="panel-head"><h2>Your week at a glance</h2><button class="text-button" data-view="plan">Full plan ${icon('arrow')}</button></div>${weekStrip()}<div class="panel-foot">Walking, a little strength, and time to recover. Your pace matters.</div></section><section class="panel"><div class="panel-head"><h2>Today’s entries</h2><button class="text-button" data-action="quick">Add ${icon('plus')}</button></div>${dailyEntries(3)}</section></div>`;}
function waterPanel(){const p=profile(),t=totals(records(),selectedDate),pct=Math.min(100,t.water/p.waterTarget*100);return `<section class="panel"><div class="panel-head"><h2>A moment to hydrate</h2><span class="pill neutral">${Math.round(pct)}% of target</span></div><div class="water-layout"><div class="water-ring"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="51" stroke="#eef3f2" stroke-width="7" fill="none"/><circle cx="60" cy="60" r="51" stroke="#92b6bd" stroke-width="7" fill="none" stroke-linecap="round" stroke-dasharray="${pct*3.2044} 320.44"/></svg><div class="ring-label"><strong>${t.water?n(t.water/1000,2):'0'}</strong><span>litres logged</span></div></div><div class="water-info"><h3>${t.water>=p.waterTarget?'Daily target reached':'Little sips, all day'}</h3><p>${n(Math.max(0,p.waterTarget-t.water))} ml to your daily target</p><div class="button-group">${[250,500].map(ml=>button(`+ ${ml} ml`,`water-${ml}`)).join('')}</div><button class="text-button mt" data-action="add-water">Custom amount</button></div></div><div class="cups" aria-hidden="true">${Array.from({length:Math.min(12,Math.ceil(p.waterTarget/250))},(_,i)=>icon('cup',`cup ${t.water>=(i+1)*250?'filled':''}`)).join('')}</div><div class="panel-foot">An editable starting target. Needs vary with heat, sweat and medical advice.</div></section>`;}
function weekStrip(){const p=profile(),day=new Date(`${selectedDate}T12:00:00Z`).getUTCDay(),monday=addDays(selectedDate,-((day+6)%7));return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const d=addDays(monday,i),plan=planFor(d,p),done=workoutDone(plan,totals(records(),d));return `<div class="day ${d===selectedDate?'today':''} ${done?'done':''}"><div class="day-name">${dayNames[new Date(`${d}T12:00:00Z`).getUTCDay()]}</div><div class="day-num">${Number(d.slice(-2))}</div>${icon(done?'check':plan.type==='Walk'?'walk':plan.type==='Strength'?'protein':'leaf')}<div class="day-type">${plan.type==='Preparation'?'Prep':plan.type==='Recovery'?'Rest':plan.type}</div></div>`;}).join('')}</div>`;}
function entryHTML(r){
  const d=r.data,time=d.time?`${d.time} IST`:'Time not recorded';
  let ico='food',name=d.name,sub='',val='',unit='';
  if(r.type==='meal'){
    sub=`${d.meal} · ${time}${d.portion?` · ${d.portion}`:''}`;val=`${n(d.calories)} kcal`;unit=`${n(d.protein,1)} g protein`;
  }
  if(r.type==='water'){ico='water';name='Water';sub=time;val=`${n(d.ml)} ml`;}
  if(r.type==='activity'){
    ico=d.kind==='Strength'?'protein':'walk';name=d.kind;
    sub=[time,d.feeling,d.effort?`Effort ${d.effort}/10`:null,d.distance!=null?`${n(d.distance,2)} km`:null].filter(Boolean).join(' · ');
    val=`${n(d.minutes)} min`;unit=d.heartRate?`${n(d.heartRate)} bpm`:'';
  }
  if(r.type==='measurement'){
    ico='weight';name=measurementKind(d)==='dexa'?'DEXA scan':'Body measurements';
    sub=[...measurementFields(measurementKind(d)).filter(k=>d[k]!==null&&d[k]!==undefined&&d[k]!=='').map(k=>`${k}: ${d[k]}${k==='weight'||k==='leanMass'?' kg':k==='bodyFat'?'%':k==='visceralFat'?' cm²':' cm'}`),...(d.time?[time]:[])].join(' · ');
  }
  return `<article class="entry"><span class="entry-icon">${icon(ico)}</span><div class="spacer"><h3>${escape(name)}</h3><p>${escape(sub)}</p></div><div class="entry-number">${val}<small>${unit}</small></div><div class="entry-actions"><button data-edit="${r.id}" aria-label="Edit ${escape(name)}">${icon('edit')}</button><button data-delete="${r.id}" aria-label="Delete ${escape(name)}">${icon('trash')}</button></div></article>`;
}
function dailyEntries(limit=0){const list=records().filter(r=>r.date===selectedDate&&['meal','water','activity','measurement'].includes(r.type)).sort((a,b)=>(b.data.time||'').localeCompare(a.data.time||'')||(b.updatedAt||'').localeCompare(a.updatedAt||'')||b.id.localeCompare(a.id));return list.length?`<div class="activity-list">${(limit?list.slice(0,limit):list).map(entryHTML).join('')}</div>${limit&&list.length>limit?`<button class="text-button mt" data-action="all-entries">View all ${list.length} entries</button>`:''}`:empty('Your day is a blank page','Your meals, water and movement will appear here when you log them.','quick','Add your first entry');}
function foodView(){const t=totals(records(),selectedDate);return `${heading('Nourish your progress.','Simple meals. Enough protein. A little more awareness.',true,'add-meal','Log a meal')}${metricsHTML()}<div class="today-grid"><section class="panel"><div class="panel-head"><h2>Your food diary</h2><button class="text-button" data-action="saved-foods">Saved meals ${icon('right')}</button></div>${['Breakfast','Lunch','Dinner','Snack'].map(group=>{const entries=t.meals.filter(r=>r.data.meal===group);return `<div class="meal-group"><div class="meal-heading"><h3>${group}</h3><small>${entries.length?`${n(entries.reduce((s,r)=>s+r.data.calories,0))} kcal`:'Not logged'}</small></div>${entries.length?entries.map(entryHTML).join(''):`<div class="meal-placeholder">Nothing logged yet. <button class="text-button" data-meal="${group}">Add ${group.toLowerCase()}</button></div>`}</div>`;}).join('')}<div class="panel-foot"><label class="checkbox"><input type="checkbox" id="food-complete" ${t.checkin.foodComplete?'checked':''}> My food log is complete for this day</label><p class="mt">Only completed food days contribute to calorie and protein averages. Enter values from food labels or a trusted food database.</p></div></section><div class="stack">${waterPanel()}<section class="panel"><div class="panel-head"><h2>Water entries</h2>${button('Add','add-water','','plus')}</div>${records().filter(r=>r.type==='water'&&r.date===selectedDate).map(entryHTML).join('')||empty('No water logged','Use the quick buttons above or enter a custom amount.','','','water')}</section><div class="note">${icon('info')}Watch calorie estimates stay separate from your food target. An incomplete diary does not mean you ate too little.</div></div></div>`;}
function activityView(){const p=profile(),plan=planFor(selectedDate,p),t=totals(records(),selectedDate);return `${heading('Find your rhythm.','Walking is a strong start. Consistency comes before speed.',true,'add-activity','Log a session')}${heroHTML()}<div class="grid2"><section class="panel"><div class="panel-head"><h2>Your movement log</h2><span class="pill neutral">${n(t.minutes)} min logged</span></div>${t.activities.length?t.activities.map(entryHTML).join(''):empty('Your next step starts here','Record what you actually did, even if it differs from your plan.','add-activity','Log movement','walk')}<div class="panel-foot">${plan.type==='Preparation'?'Your structured plan has not started. Optional comfortable movement is welcome.':workoutDone(plan,t)?'Your planned session is marked complete.':plan.type==='Recovery'?'Recovery is on your plan today. Check in when you finish the day.':'Your session is not yet marked complete. Partial activity still counts toward your logged minutes.'}</div></section><section class="panel"><div class="panel-head"><h2>Samsung Watch companion</h2>${icon('heart')}</div><p class="muted small">Enter readings from your watch or Samsung Health after your session. You can record heart rate and estimated exercise calories with each workout, and steps and sleep in your daily check-in.</p><div class="note mt">Manual entry only. There is no automatic watch connection in this version.</div>${button('Log steps & recovery','checkin','mt','plus')}<div class="panel-foot">Use how you feel and the talk test to guide easy walks. Watch calories are estimates and do not increase your food target.</div></section><section class="panel full"><div class="panel-head"><h2>A week that leaves room for life</h2><span class="small muted">${escape(p.workoutTime)} IST</span></div>${weekStrip()}</section></div>`;}
function weightChart(points){if(!points.length)return empty('A baseline for your progress','Set your starting weight or add your first measurement.','add-measurement','Add measurement','chart');if(points.length===1)return empty(`${n(points[0].weight,1)} kg · Your starting point`,'Add another dated weight to see a trend. A single reading cannot show a rate of change.','add-measurement','Log a measurement','chart');const width=620,height=210,left=42,right=18,top=20,bottom=32;const vals=points.map(p=>p.weight),lo=Math.min(...vals)-.8,hi=Math.max(...vals)+.8,first=points[0].date,last=points.at(-1).date,span=Math.max(1,dayDiff(last,first));const x=d=>left+dayDiff(d,first)/span*(width-left-right),y=w=>top+(hi-w)/(hi-lo)*(height-top-bottom);const line=points.map((p,i)=>`${i?'L':'M'}${x(p.date)},${y(p.weight)}`).join(' ');return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Weight trend from ${escape(first)} to ${escape(last)}"><defs><linearGradient id="weight-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#a7bc89" stop-opacity=".25"/><stop offset="100%" stop-color="#a7bc89" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=lo+i*(hi-lo)/3;return `<line x1="${left}" y1="${y(v)}" x2="${width-right}" y2="${y(v)}" stroke="#edf0e8" stroke-dasharray="4 4"/><text x="0" y="${y(v)+4}">${n(v,1)}</text>`;}).join('')}<path d="${line} L${x(last)},${height-bottom} L${x(first)},${height-bottom}Z" fill="url(#weight-fill)"/><path d="${line}" fill="none" stroke="#73925f" stroke-width="2.5"/>${points.map(p=>`<circle cx="${x(p.date)}" cy="${y(p.weight)}" r="4" fill="#73925f" stroke="white" stroke-width="2"><title>${p.date}: ${p.weight} kg</title></circle>`).join('')}<text x="${left}" y="${height-5}">${friendly(first,true)}</text><text x="${width-right}" y="${height-5}" text-anchor="end">${friendly(last,true)}</text></svg><div class="chart-caption"><span><span class="legend-dot"></span>Logged weight · kg</span><span>Daily fluctuations are normal</span></div>`;}
function progressView(){const p=profile(),all=records(),analysis=analyze(all,p,selectedDate,range),weights=trend(all,p),latest=weights.at(-1),delta=weights.length>1?latest.weight-weights[0].weight:null;const measurements=all.filter(r=>r.type==='measurement').sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));const waist=measurements.find(r=>r.data.waist);return `${heading('See the bigger picture.','Look for trends, not perfect days.',true,'add-measurement','Add measurement')}<div class="grid3 mb"><div class="mini-stat"><span class="label">Latest weight</span><strong>${latest?n(latest.weight,1):'—'} <small>kg</small></strong><small>${delta===null?'A starting point, not a trend':`${delta>0?'+':''}${n(delta,1)} kg from baseline`}</small></div><div class="mini-stat"><span class="label">Latest waist</span><strong>${waist?n(waist.data.waist,1):'—'} <small>cm</small></strong><small>${waist?friendly(waist.date,true):'No waist measurement yet'}</small></div><div class="mini-stat"><span class="label">Planned sessions completed</span><strong>${analysis.exerciseCompleted} <small>/ ${analysis.exercisePlanned}</small></strong><small>Last ${range} days · Due sessions only</small></div></div><div class="grid2"><section class="panel"><div class="panel-head"><h2>Weight, over time</h2><span class="pill neutral">${weights.length} dated readings</span></div>${weightChart(weights)}</section><section class="panel"><div class="panel-head"><h2>Your weekly perspective</h2><div class="segmented">${[7,30].map(d=>`<button data-range="${d}" class="${range===d?'active':''}">${d} days</button>`).join('')}</div></div><div class="insight"><h3>${analysis.exercisePlanned?`${analysis.exerciseCompleted} of ${analysis.exercisePlanned} planned sessions completed`:'Your plan is just getting started'}</h3><p>${analysis.minutes} total minutes logged in this period. Badminton can substitute for a planned walking session when the logged time meets the target.</p></div><div class="insight"><h3>${analysis.foodDays?`${n(analysis.averageProtein)} g average protein`:'More food data will help'}</h3><p>${analysis.foodDays?`${analysis.foodDays} completed food day${analysis.foodDays===1?'':'s'} · Target met on ${analysis.proteinDays}. ${analysis.averageCalories} kcal average on those completed days.`:'Mark a food diary complete after logging the whole day. Partial days are excluded from food averages.'}</p></div><div class="insight"><h3>${analysis.waterDays?`${n(analysis.averageWater)} ml average water logged`:'Build your hydration habit'}</h3><p>${analysis.waterDays?`Based on ${analysis.waterDays} days with water entries. Days without entries are unknown, not zero intake.`:'Add water as you drink it. A missing entry does not mean you drank nothing.'}</p></div></section><section class="panel full"><div class="panel-head"><h2>Your measurement history</h2><button class="text-button" data-action="add-measurement">New entry ${icon('plus')}</button></div>${measurements.length?`<div class="table-scroll"><table><thead><tr><th>Date</th><th>Weight · kg</th><th>Waist · cm</th><th>Chest · cm</th><th>Hips · cm</th><th>Arm · cm</th><th>Fat · %</th><th>Actions</th></tr></thead><tbody>${measurements.map(r=>`<tr><td>${friendly(r.date,true)}</td>${['weight','waist','chest','hips','arm','bodyFat'].map(k=>`<td>${r.data[k]??'—'}</td>`).join('')}<td><div class="entry-actions"><button data-edit="${r.id}" aria-label="Edit measurement">${icon('edit')}</button><button data-delete="${r.id}" aria-label="Delete measurement">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Make your progress visible','Weekly measurements under similar conditions are more useful than frequent checks.','add-measurement','Add your measurements','weight')}</section><section class="panel full"><div class="panel-head"><h2>Your DEXA baseline</h2><button class="text-button" data-action="baseline">View baseline ${icon('edit')}</button></div><div class="grid3"><div class="mini-stat"><span class="label">Body fat</span><strong>${p.bodyFat??'—'} <small>%</small></strong><small>${p.baselineDate?friendly(p.baselineDate,true):'Add from your report'}</small></div><div class="mini-stat"><span class="label">Lean soft tissue</span><strong>${p.leanMass??'—'} <small>kg</small></strong><small>Includes more than muscle</small></div><div class="mini-stat"><span class="label">Estimated visceral fat</span><strong>${p.visceralFat??'—'} <small>cm²</small></strong><small>Discuss with your clinician</small></div></div><div class="panel-foot">These are scan estimates, not daily targets or diagnoses. Future DEXA values can be saved in a measurement entry.</div></section></div>`;}
function planView(){const p=profile();return `${heading('A plan that grows with you.','Start gently. Get consistent. Build from there.',false,'profile','Edit your plan')}<div class="grid2"><section class="panel"><div class="panel-head"><h2>Your first four weeks</h2><span class="pill">${escape(p.workoutTime)} IST</span></div><div class="plan-week"><h3>Week 1 · Find your starting pace</h3><p>Three 15-minute comfortable walks. Include easy warm-up and cool-down minutes within each session. Shorten a session if needed.</p><span class="exercise-chip">Talk in full sentences</span></div><div class="plan-week"><h3>Week 2 · Make it a habit</h3><p>Try 20 minutes per walking session if week one felt comfortable. Repeat the previous week when recovery needs more time.</p></div><div class="plan-week"><h3>Week 3 · A little more time</h3><p>Build toward 25 minutes. Keep the effort easy to moderate; speed and incline are optional.</p></div><div class="plan-week"><h3>Week 4 onward · Stay steady</h3><p>Work toward 30-minute walks. Add more weekly activity gradually as tolerated. Running is optional, not required for fat loss.</p></div><div class="note mt">Progression is a suggestion. Stop a session for chest pain, faintness or unusual breathlessness and seek appropriate medical help.</div></section><section class="panel"><div class="panel-head"><h2>Your weekly rhythm</h2><span class="small muted">Starts ${friendly(p.startDate,true)}</span></div>${dayNames.map((day,i)=>`<div class="check-row"><span class="check-icon">${icon(p.exerciseDays.includes(i)?'walk':p.strengthDays.includes(i)?'protein':'leaf')}</span><div class="spacer"><h3>${day}</h3><p>${p.exerciseDays.includes(i)?'Comfortable treadmill walk':p.strengthDays.includes(i)?'Beginner full-body strength':'Recovery · optional easy movement'}</p></div><span class="tiny muted">${p.exerciseDays.includes(i)||p.strengthDays.includes(i)?escape(p.workoutTime)+' IST':'Flexible'}</span></div>`).join('')}<div class="panel-foot">Badminton can replace a walking session. Build toward general activity guidance over time; this is a starting plan.</div></section><section class="panel"><div class="panel-head"><h2>Strength supports your shape</h2>${icon('protein')}</div><p class="muted small">Two short sessions weekly can help preserve muscle while losing fat. Begin with 1–2 comfortable sets of 8–12 controlled repetitions, leaving a few repetitions in reserve.</p><div class="mt">${['Chair squat or assisted squat','Wall or incline push-up','Supported row with a light weight','Glute bridge','Light carry or gentle core work'].map(s=>`<div class="check-row"><span class="check-icon">${icon('check')}</span><h3>${s}</h3></div>`).join('')}</div><div class="panel-foot">Ask a trainer to check your technique. Compare actual strength between arms rather than adding extra work based only on a scan.</div></section><section class="panel"><div class="panel-head"><h2>Estimate your starting targets</h2>${icon('chart')}</div><form id="calculator-form" class="form-grid"><div class="field full"><label for="calc-activity">Usual activity level</label><select id="calc-activity" name="factor"><option value="1.2">Mostly seated, little exercise</option><option value="1.375" selected>Light activity / starting exercise</option><option value="1.55">Moderately active</option></select></div><div class="field full"><label for="calc-deficit">Daily calorie reduction</label><select id="calc-deficit" name="deficit"><option value="0">Maintenance estimate</option><option value="250" selected>Gentle reduction · 250 kcal</option><option value="350">Moderate reduction · 350 kcal</option></select></div><div class="full">${button('Calculate estimate','calculate','','chart')}</div></form><div id="calculator-result"></div><div class="panel-foot">Uses Mifflin–St Jeor with your profile and latest weight. Activity factors are rough estimates. Review a few weeks of actual trends before adjusting intake.</div><p class="small muted mt">Your protein target is ${p.proteinTarget} g/day and water target is ${n(p.waterTarget)} ml/day. Both are editable; follow medical advice if you have restrictions.</p></section>${projectionPanel()}<section class="panel full"><div class="panel-head"><h2>Useful context, without the noise</h2>${icon('info')}</div><p class="small muted">Aim for gradual fat loss while maintaining strength. A common initial milestone is 5–10% of starting weight over around six months, then reassess. DEXA cannot determine your current calorie intake, diagnose metabolic disease, or guarantee a particular appearance.</p><div class="mt small"><a href="https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program" target="_blank" rel="noopener noreferrer">NIDDK: weight management</a> · <a href="https://jissn.biomedcentral.com/articles/10.1186/s12970-017-0177-8" target="_blank" rel="noopener noreferrer">ISSN: protein and exercise</a> · <a href="https://iscd.org/learn/official-positions/adult-positions/" target="_blank" rel="noopener noreferrer">ISCD: DEXA interpretation</a></div></section></div>`;}
function settingsView(){const conflicts=store.state.queue.filter(q=>q.conflict||q.error);return `${heading('Your space, your settings.','Your goals can change. Your records stay yours.',false,'','')}<div class="grid2"><section class="panel"><div class="panel-head"><h2>Tenzo’s plan</h2>${icon('settings')}</div><p class="muted small">Your DEXA details are already configured for Tenzo. Adjust your workout schedule, water, protein and optional calorie targets.</p>${button('Edit daily goals & plan','profile','mt','edit')}<div class="panel-foot">All log dates use Asia/Kolkata. Your workout time is a plan reference; this app does not send scheduled notifications.</div></section><section class="panel"><div class="panel-head"><h2>Cloud connection</h2>${statusHTML()}</div><p class="small muted">Signed in as ${escape(session.email)}. ${store.state.queue.length} pending change${store.state.queue.length===1?'':'s'} on this device.</p><div class="button-group mt">${button('Sync now','sync','','sync')}${button('Reconnect sign-in','login','','shield')}</div><div class="panel-foot">Online devices check for changes every 30 seconds and when you return to the app. Offline entries sync when the app is open and connected.</div></section><section class="panel"><div class="panel-head"><h2>Keep a copy</h2>${icon('download')}</div><p class="small muted">Export your profile, logs and unsynced changes as JSON. Backups contain personal health data, so store them somewhere private.</p><div class="button-group mt">${button('Export backup','export','','download')}${button('Import backup','import','','plus')}</div><div class="panel-foot">Import merges by record ID, shows a confirmation, and queues changes for cloud sync. It does not erase other cloud records.</div></section><section class="panel"><div class="panel-head"><h2>Make it your daily companion</h2>${icon('home')}</div><p class="small muted">Install Gym Buddy for a home-screen shortcut and offline logging after your first successful sign-in and app load.</p>${button(installPrompt?'Install Gym Buddy':'How to install','install','mt','plus')}<div class="panel-foot">Offline records stay on this device. Sign out and remove this device’s copy before sharing it with someone else.</div></section><section class="panel full"><div class="panel-head"><h2>Sync review</h2><span class="pill ${conflicts.length?'warn':'neutral'}">${conflicts.length} to review</span></div>${conflicts.length?conflicts.map(q=>`<div class="conflict"><h3>${q.error?'Entry needs attention':'This entry changed on another device'}</h3><p class="small muted mt">${escape(q.error||'Choose which version to keep. Nothing will overwrite the cloud copy until you choose.')} · ${escape(q.record.type)} · ${q.record.date}</p><div class="grid2"><div><span class="tiny muted">THIS DEVICE</span><pre>${escape(JSON.stringify(q.record.data,null,2))}</pre></div><div><span class="tiny muted">CLOUD</span><pre>${escape(q.conflict?.current?JSON.stringify(q.conflict.current.data,null,2):'No cloud copy')}</pre></div></div><div class="button-group">${q.conflict?`<button class="btn primary" data-resolve="${q.operationId}" data-choice="local">Keep this device’s version</button><button class="btn" data-resolve="${q.operationId}" data-choice="cloud">Use cloud version</button>`:`<button class="btn" data-discard="${q.operationId}">Discard queued change & reload cloud</button>`}</div></div>`).join(''):empty('Everything is in step','Conflicting edits from two devices will appear here for you to resolve.','','','cloud')}</section><section class="panel full"><div class="panel-head"><h2>Device privacy</h2>${icon('shield')}</div><p class="small muted">Cloud records are protected by private sign-in. Offline copies are stored in this browser and are accessible to anyone who can use its signed-in profile. Clearing browser data removes unsynced entries.</p>${button('Sign out & remove device copy','signout','danger mt','logout')}</section></div>`;}

function field(name,label,value='',options={}){const {type='text',min,max,step,required=false,help='',full=false,placeholder=''}=options;return `<div class="field ${full?'full':''}"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${escape(value??'')}" ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`${type==='text'?'maxlength':'max'}="${max}"`:''} ${step?`step="${step}"`:''} ${required?'required':''} ${placeholder?`placeholder="${escape(placeholder)}"`:''}>${help?`<small>${help}</small>`:''}</div>`;}
function select(name,label,values,value,full=false){return `<div class="field ${full?'full':''}"><label for="field-${name}">${label}</label><select id="field-${name}" name="${name}">${values.map(v=>{const [key,label]=Array.isArray(v)?v:[v,v];return `<option value="${escape(key)}" ${String(key)===String(value)?'selected':''}>${escape(label)}</option>`;}).join('')}</select></div>`;}
const notesField=(value,max=1000,label='Notes')=>`<div class="field full"><label for="field-notes">${label} <span class="muted">(optional)</span></label><textarea id="field-notes" name="notes" maxlength="${max}" placeholder="Anything you’d like to remember">${escape(value||'')}</textarea></div>`;
function openDialog(title,subtitle,body,{form=false,submit='Save entry',closable=true}={}){
  const dialog=$('#entry-dialog');if(dialog.open)dialog.close();
  dialog.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${closable?`<button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button>`:''}</div><div class="dialog-body">${form?`<form id="entry-form">${body}<div id="form-error" role="alert"></div><div class="dialog-foot">${button('Cancel','close-dialog')}<button class="btn primary" type="submit">${submit}</button></div></form>`:body}</div>`;
  dialog.showModal();
}
function formEntry(type,id,defaults={}){
  if(!hasProfile()){toast('Your private baseline has not synced yet. Reconnect and retry.');return;}
  const existing=id?store.state.records[id]:null,d={...existing?.data,...defaults};
  const filled=key=>d[key]!==null&&d[key]!==undefined&&d[key]!=='';
  const date=defaults.date||existing?.date||selectedDate;
  currentForm={type,id:existing?.id||id||uuid(),existing};
  const dateField=field('date','Date · IST',date,{type:'date',required:true,max:dateIST(),full:true});
  const timeValue=d.time??(!existing&&date===dateIST()?timeIST():'');
  const eventTime=(label='Time · IST',required=true)=>field('time',label,timeValue,{type:'time',required:required&&(!existing||!!d.time),help:existing&&!d.time?'Time was not recorded for this older entry. Leave blank if unknown.':''});
  const more=(title,contents,open=false)=>`<details class="entry-details full" ${open?'open':''}><summary>${title}</summary><div class="form-grid">${contents}</div></details>`;
  let body='',title='';
  if(type==='water'){
    title='water';
    body=dateField+field('ml','Water · ml',d.ml??250,{type:'number',min:1,max:3000,step:1,required:true})+eventTime();
  }
  if(type==='meal'||type==='food'){
    title=type==='food'?'a saved meal':'a meal';
    body=(type==='meal'?dateField+select('meal','Meal',['Breakfast','Lunch','Dinner','Snack'],d.meal||'Breakfast')+eventTime():'')
      +field('name','Food / meal name',d.name,{required:true,max:100,full:true})
      +field('portion','Portion',d.portion,{placeholder:'e.g. 2 rotis + 1 cup dal',full:true,max:100})
      +field('calories','Calories · kcal',d.calories,{type:'number',min:0,max:5000,step:1,required:true})
      +field('protein','Protein · g',d.protein,{type:'number',min:0,max:300,step:.1,required:true})
      +more('Notes (optional)',notesField(d.notes,500),!!d.notes)
      +(type==='meal'&&!existing?'<label class="checkbox full"><input type="checkbox" name="saveFood"> Save this meal for quick reuse</label>':'')
      +'<div class="note full">Use label values or a trusted nutrition database. Nutrition is not inferred from the meal name.</div>';
  }
  if(type==='activity'){
    title='a session';
    const kind=d.kind||'Treadmill walk',fields=activityFields(kind);
    body=dateField+select('kind','Activity',ACTIVITY_KINDS,kind,true)
      +field('minutes','Duration · minutes',d.minutes,{type:'number',min:1,max:480,step:1,required:true})+eventTime('Start time · IST');
    if(fields.includes('distance'))body+=field('distance','Distance · km (optional)',d.distance,{type:'number',min:0,max:100,step:.01,full:true});
    if(fields.includes('speed'))body+=more('Treadmill settings (optional)',field('speed','Treadmill speed · km/h',d.speed,{type:'number',min:0,max:30,step:.1})+field('incline','Incline · %',d.incline,{type:'number',min:0,max:30,step:.5}),filled('speed')||filled('incline'));
    body+=more('Effort & session notes (optional)',
      select('effort','Perceived effort · 1–10',[['','Not recorded'],...Array.from({length:10},(_,i)=>[i+1,`${i+1}${i===0?' · Very easy':i===4?' · Moderate':i===9?' · Maximum':''}`])],d.effort??'')
      +select('feeling','How did it feel?',[['','Not recorded'],'Good','Okay','Hard'],d.feeling??'')
      +notesField(d.notes,1000,kind==='Strength'?'Exercises, sets, reps or notes':'Session notes'),!!(d.effort||d.feeling||d.notes));
    body+=more('Samsung Watch readings (optional)',field('heartRate','Average heart rate · bpm',d.heartRate,{type:'number',min:30,max:240,step:1})+field('watchCalories','Estimated exercise calories',d.watchCalories,{type:'number',min:0,max:5000,step:1}),filled('heartRate')||filled('watchCalories'));
  }
  if(type==='measurement'){
    title='measurements';
    const kind=measurementKind(d),options=[['body','Body measurements'],['dexa','DEXA scan']];
    if(kind==='combined')options.push(['combined','Older combined entry']);
    body=dateField+select('measurementKind','Measurement type',options,kind,true);
    const definitions={
      weight:['Weight · kg',30,350,.01],waist:['Waist · cm',30,250,.1],chest:['Chest · cm',30,250,.1],hips:['Hips · cm',30,250,.1],arm:['Arm · cm',10,100,.1],
      bodyFat:['Body fat · % (scan only)',3,65,.1],leanMass:['Lean soft tissue · kg (scan)',10,200,.01],visceralFat:['Visceral fat · cm² (scan)',0,1000,.1]
    };
    for(const name of measurementFields(kind)){const [label,min,max,step]=definitions[name];body+=field(name,label,d[name],{type:'number',min,max,step});}
    const measuredTime=d.time??'';
    body+=more('Time & notes (optional)',field('time','Measured at · IST',measuredTime,{type:'time'})+notesField(d.notes,500),!!(d.time||d.notes));
    body+=`<div class="note full">${kind==='dexa'?'Enter values from the new scan. Your original DEXA baseline stays unchanged.':kind==='combined'?'This older entry contains both body and scan values. Both are shown so you can preserve them.':'Enter only the measurements you took. Keep waist measurements consistent. DEXA fields are available by choosing DEXA scan.'}</div>`;
  }
  openDialog(`${existing?'Edit':'Log'} ${title}`,type==='food'?'Reusable nutrition values; date and time are chosen when you eat it.':`For ${friendly(date,true)} · IST`,`<div class="form-grid">${body}</div>`,{form:true});
}
function profileForm(){
  if(!hasProfile())return toast('Reconnect to load Tenzo’s private baseline.');
  const p=profile();
  currentForm={type:'profile',id:'profile',existing:store.state.records.profile};
  const days=(name,values)=>`<div class="field full"><label>${name==='exerciseDays'?'Walking days':'Strength days'}</label><div class="day-checkboxes">${dayNames.map((label,i)=>`<label><input type="checkbox" name="${name}" value="${i}" ${values.includes(i)?'checked':''}>${label}</label>`).join('')}</div></div>`;
  openDialog('Tenzo’s plan','Your DEXA baseline is already configured.',`<div class="form-grid"><div class="note full">Your personal details come from your report. Adjust daily goals and workout settings here.</div>${field('goalWeight','Goal weight · kg (optional)',p.goalWeight,{type:'number',min:30,max:350,step:.1})}${field('proteinTarget','Protein · g',p.proteinTarget,{type:'number',min:30,max:250,step:1,required:true})}${field('waterTarget','Water · ml',p.waterTarget,{type:'number',min:500,max:6000,step:50,required:true})}${field('calorieTarget','Calories · kcal (optional)',p.calorieTarget,{type:'number',min:1200,max:5000,step:50,help:'Optional. The calculator can provide a starting estimate.'})}<h3 class="form-heading full">Your exercise plan</h3>${field('startDate','Plan start date',p.startDate,{type:'date',required:true})}${field('workoutTime','Workout time · IST',p.workoutTime,{type:'time',required:true})}${days('exerciseDays',p.exerciseDays)}${days('strengthDays',p.strengthDays)}<div class="note full">Start gently and adjust to recovery. Water and protein needs vary; follow medical advice if you have dietary or fluid restrictions.</div></div>`,{form:true,submit:'Save plan'});
}
function baselineDialog(){
  const p=profile();
  const items=[['Scan date',p.baselineDate],['Height',p.height?`${n(p.height)} cm`:'—'],['Age at scan',p.age?`${p.age} years`:'—'],['Starting weight',p.initialWeight?`${n(p.initialWeight,2)} kg`:'—'],['Body fat',p.bodyFat?`${n(p.bodyFat,1)}%`:'—'],['Lean soft tissue',p.leanMass?`${n(p.leanMass,2)} kg`:'—'],['Estimated visceral fat',p.visceralFat?`${n(p.visceralFat)} cm²`:'—']];
  openDialog('Tenzo’s DEXA baseline','Loaded from your report.',`<table><tbody>${items.map(([label,value])=>`<tr><td>${label}</td><td>${escape(value||'—')}</td></tr>`).join('')}</tbody></table><div class="note mt">Your original scan stays as the baseline. Log new measurements in Progress.</div>`);
}

function checkinForm(){
  if(!hasProfile())return toast('Reconnect to load your private baseline.');
  const existing=store.state.records[`checkin-${selectedDate}`],d=existing?.data||{};
  const recovery=planFor(selectedDate,profile()).type==='Recovery'||d.recoveryDone;
  currentForm={type:'checkin',id:`checkin-${selectedDate}`,existing};
  openDialog('Your daily check-in',`${friendly(selectedDate)} · IST`,`<div class="form-grid"><label class="checkbox full"><input type="checkbox" name="foodComplete" ${d.foodComplete?'checked':''}> My food diary is complete for this day</label>${recovery?`<label class="checkbox full"><input type="checkbox" name="recoveryDone" ${d.recoveryDone?'checked':''}> I completed my planned recovery / rest day</label>`:''}<details class="entry-details full" ${d.steps!=null||d.sleep!=null?'open':''}><summary>Daily watch readings (optional)</summary><div class="form-grid">${field('steps','Watch steps · optional',d.steps,{type:'number',min:0,max:150000,step:1})}${field('sleep','Sleep · hours (optional)',d.sleep,{type:'number',min:0,max:24,step:.1})}</div></details><details class="entry-details full" ${d.notes?'open':''}><summary>Daily notes (optional)</summary><div class="form-grid">${notesField(d.notes)}</div></details></div>`,{form:true,submit:'Save check-in'});
}

async function saveForm(form){const fd=new FormData(form),num=k=>fd.get(k)===''||fd.get(k)===null?null:Number(fd.get(k)),str=k=>String(fd.get(k)||'').trim();let data={},date=str('date')||selectedDate;const type=currentForm.type;
  if(type==='profile') {const settings={};for(const k of ['startDate','workoutTime'])settings[k]=str(k);for(const k of ['goalWeight','proteinTarget','waterTarget','calorieTarget'])settings[k]=num(k);for(const k of ['exerciseDays','strengthDays'])settings[k]=fd.getAll(k).map(Number);data=updatePlan(profile(),settings);date=data.baselineDate;}
  if(type==='water')data={ml:num('ml'),time:str('time')};
  if(type==='meal'||type==='food')data={time:str('time'),name:str('name'),meal:str('meal'),portion:str('portion'),calories:num('calories'),protein:num('protein'),notes:str('notes')};
  if(type==='activity'){for(const k of ['kind','time','feeling','notes'])data[k]=str(k);for(const k of ['minutes','distance','speed','incline','effort','heartRate','watchCalories'])data[k]=num(k);}
  if(type==='measurement'){for(const k of ['weight','waist','chest','hips','arm','bodyFat','leanMass','visceralFat'])data[k]=num(k);data.notes=str('notes');data.time=str('time');data.measurementKind=str('measurementKind');}
  if(type==='checkin'){data={foodComplete:fd.has('foodComplete'),recoveryDone:fd.has('recoveryDone'),steps:num('steps'),sleep:num('sleep'),notes:str('notes')};}
  if(type!=='profile')data=entryData(type,data);
  const record={id:currentForm.id,type,date:type==='food'&&currentForm.existing?currentForm.existing.date:date,data,deleted:false,updatedAt:new Date().toISOString()};
  validateRecord(record);await store.save(record);
  if(type==='meal'&&fd.has('saveFood'))await store.save({id:uuid(),type:'food',date,data:entryData('food',data),deleted:false,updatedAt:new Date().toISOString()});
  $('#entry-dialog').close();shell();toast('Saved on this device. Cloud sync will follow.');
}

function quickDialog(){openDialog('What would you like to log?',`For ${friendly(selectedDate,true)} · IST`,`<div class="quick-grid">${[['add-meal','food','Food','Calories & protein'],['add-water','water','Water','Every glass counts'],['add-activity','walk','Movement','Treadmill, strength or badminton'],['add-measurement','weight','Measurements','Weight, waist & more'],['checkin','heart','Daily check-in','Steps, sleep & recovery'],['saved-foods','plan','Saved meals','Reuse a familiar meal']].map(([action,i,title,sub])=>`<button class="quick-button" data-action="${action}">${icon(i)}<strong>${title}</strong><small>${sub}</small></button>`).join('')}</div>`);}
function savedFoods(){const list=records().filter(r=>r.type==='food');openDialog('Your saved meals','A familiar meal, a little faster.',list.length?list.map(r=>`<div class="entry"><span class="entry-icon">${icon('food')}</span><div class="spacer"><h3>${escape(r.data.name)}</h3><p>${escape(r.data.portion||'')} · ${r.data.calories} kcal · ${r.data.protein} g protein</p></div><button class="btn" data-reuse="${r.id}">Use</button><button class="icon-button" data-edit="${r.id}" aria-label="Edit saved meal">${icon('edit')}</button><button class="icon-button" data-delete="${r.id}" aria-label="Delete saved meal">${icon('trash')}</button></div>`).join(''):empty('Your go-to meals live here','Tick “Save this meal” when you log food.','add-meal','Log a meal','food'));}
async function downloadBackup(){await store.read();const blob=new Blob([JSON.stringify({format:'gym-buddy',version:1,owner:session.email,exportedAt:new Date().toISOString(),records:Object.values(store.state.records),pending:store.state.queue},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`gym-buddy-${dateIST()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded. Store it privately.');}
async function importBackup(file){try{if(file.size>10*1024*1024)throw new Error('Choose a backup smaller than 10 MB.');const data=JSON.parse(await file.text());if(data.format!=='gym-buddy'||data.version!==1||!Array.isArray(data.records)||data.records.length>10000)throw new Error('This is not a supported Gym Buddy backup.');if(data.owner&&data.owner!==session.email)throw new Error('This backup belongs to another account.');const ids=new Set();for(const r of data.records){validateRecord(r);if(ids.has(r.id))throw new Error('The backup contains duplicate record IDs.');ids.add(r.id);}openDialog('Import your backup',`${data.records.length} records · Review before importing.`,`<p class="small muted">This merges entries by ID. Existing entries with the same ID will use the backup values after cloud conflict checks. Other records remain. Export a current backup first if you want to preserve both versions.</p><div class="dialog-foot">${button('Cancel','close-dialog')}<button class="btn primary" id="confirm-import">Import ${data.records.length} records</button></div>`);$('#confirm-import').onclick=async()=>{try{await store.update(s=>{for(const r of data.records){if(r.type==='profile'&&r.deleted)throw new Error('A profile cannot be deleted.');queueChange(s,{...r,version:undefined,updatedAt:new Date().toISOString()});}});$('#entry-dialog').close();shell();toast('Backup imported. Syncing your changes.');void store.sync();}catch(e){toast(e.message);}};}catch(e){toast(e.message||'Could not read this backup.');}}
function calculate(){const fd=new FormData($('#calculator-form')),p=profile(),weights=trend(records(),p),r=calorieEstimate(p,weights.at(-1)?.weight,Number(fd.get('factor')),Number(fd.get('deficit')));if(!r){$('#calculator-result').innerHTML='<div class="note warn mt">Reconnect to load your configured DEXA baseline, then calculate again.</div>';return;}$('#calculator-result').innerHTML=`<div class="calculator-result"><div><strong>${n(r.bmr)}</strong><span>Resting estimate · kcal</span></div><div><strong>${n(r.maintenance)}</strong><span>Maintenance · kcal</span></div><div><strong>${n(r.target)}</strong><span>Starting estimate · kcal</span></div></div><p class="small muted mt">This is a starting estimate, not a measured requirement.${r.target<1500?' This estimate is low; review it with a qualified dietitian before using it.':''}</p>${r.target>=1500?`<button class="text-button mt" data-calorie-target="${r.target}">Use ${n(r.target)} kcal as my editable target ${icon('arrow')}</button>`:''}`;}
async function signout(){openDialog('Remove this device’s copy?', 'Your cloud records remain in your account.',`<p class="small muted">${store.state.queue.length?`You have ${store.state.queue.length} unsynced changes. Sync or export a backup before continuing.`:'This clears downloaded records from this browser and signs out of Cloudflare Access.'}</p><div class="dialog-foot">${button('Cancel','close-dialog')}${button('Export backup','export')}<button class="btn danger" id="confirm-signout">Remove device copy & sign out</button></div>`);$('#confirm-signout').onclick=async()=>{store.channel?.close();store.db.close();const name=`gym-buddy-v1:${session.email}`;await new Promise((res,rej)=>{const req=indexedDB.deleteDatabase(name);req.onsuccess=res;req.onerror=()=>rej(new Error('Could not remove the device copy.'));req.onblocked=()=>rej(new Error('Close other Gym Buddy tabs, then try again.'));}).catch(e=>{toast(e.message);throw e;});localStorage.removeItem('gym-buddy-last-account');location.href='/cdn-cgi/access/logout';};}

document.addEventListener('click',async event=>{
  const el=event.target.closest('button,a[data-view]');if(!el)return;
  try {
    if(el.dataset.view){view=el.dataset.view;shell();window.scrollTo({top:0});return;}
    if(el.dataset.edit){const r=store.state.records[el.dataset.edit];formEntry(r.type,r.id);return;}
    if(el.dataset.delete){const r=store.state.records[el.dataset.delete];openDialog('Delete this entry?',`${r.date} · ${r.type}`,`<p class="small muted">This deletion will sync to your other devices. Export a backup first if you want to keep a copy.</p><div class="dialog-foot">${button('Cancel','close-dialog')}<button class="btn danger" id="confirm-delete">Delete entry</button></div>`);$('#confirm-delete').onclick=async()=>{await store.remove(r.id);$('#entry-dialog').close();shell();toast('Entry deleted.');};return;}
    if(el.dataset.meal){formEntry('meal',null,{meal:el.dataset.meal});return;}
    if(el.dataset.reuse){formEntry('meal',null,store.state.records[el.dataset.reuse].data);return;}
    if(el.dataset.range){range=Number(el.dataset.range);shell();return;}
    if(el.dataset.resolve){await store.resolve(el.dataset.resolve,el.dataset.choice);shell();return;}
    if(el.dataset.discard){await store.update(s=>{const q=s.queue.find(q=>q.operationId===el.dataset.discard);if(q){s.queue=s.queue.filter(op=>op.record.id!==q.record.id);delete s.records[q.record.id];}});void store.sync();shell();return;}
    if(el.dataset.calorieTarget){const p=profile();await store.save({...store.state.records.profile,data:{...p,calorieTarget:Number(el.dataset.calorieTarget)}});toast('Calorie target updated.');return;}
    const action=el.dataset.action;if(!action)return;
    if(action.startsWith('water-')){if(selectedDate!==dateIST())return formEntry('water',null,{ml:Number(action.split('-')[1])});if(!hasProfile())return toast('Reconnect to load your private baseline.');await store.save({id:uuid(),type:'water',date:selectedDate,data:{ml:Number(action.split('-')[1]),time:timeIST()},deleted:false,updatedAt:new Date().toISOString()});toast('Water logged.');return;}
    const actions={quick:quickDialog,'add-meal':()=>formEntry('meal'),'add-water':()=>formEntry('water'),'add-activity':()=>formEntry('activity'),'add-measurement':()=>formEntry('measurement'),profile:profileForm,baseline:baselineDialog,checkin:checkinForm,'saved-foods':savedFoods,'close-dialog':()=>$('#entry-dialog').close(),'view-plan':()=>{view='plan';shell();},'previous-day':()=>{selectedDate=addDays(selectedDate,-1);shell();},'next-day':()=>{if(selectedDate<dateIST())selectedDate=addDays(selectedDate,1);shell();},sync:()=>store.sync(),'sync-details':()=>{view='settings';shell();},'all-entries':()=>openDialog('Your entries',friendly(selectedDate),dailyEntries()),export:downloadBackup,import:()=>$('#import-file').click(),calculate,'project-composition':projectComposition,login:()=>location.assign('/signin'),signout,install:async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else openDialog('Install Gym Buddy','Keep your daily companion close.',`<div class="stack"><p class="small muted"><strong>Android / Chrome:</strong> open the browser menu and choose “Install app” or “Add to Home screen”.</p><p class="small muted"><strong>iPhone / Safari:</strong> tap Share, then “Add to Home Screen”.</p><p class="small muted">First sign in and let your records sync while online. The app can then keep new entries offline until you reconnect.</p></div>`);},'update-app':()=>{if(updateWaiting){updateWaiting.postMessage('ACTIVATE_UPDATE');navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});}}};
    await actions[action]?.();
  }catch(e){toast(e.message||'Something went wrong. Please try again.');}
});
document.addEventListener('submit',async event=>{if(event.target.id==='calculator-form'){event.preventDefault();calculate();return;}if(event.target.id!=='entry-form')return;event.preventDefault();const btn=event.target.querySelector('button[type="submit"]');btn.disabled=true;try{await saveForm(event.target);}catch(e){$('#form-error').className='form-error';$('#form-error').textContent=e.message||'Could not save. Please try again.';btn.disabled=false;}});
document.addEventListener('change',async event=>{try{if(event.target.id==='field-kind'||event.target.id==='field-measurementKind'){const draft=Object.fromEntries(new FormData($('#entry-form')));formEntry(currentForm.type,currentForm.id,draft);document.getElementById(event.target.id)?.focus();return;}if(event.target.id==='selected-date'){if(event.target.value&&event.target.value<=dateIST()){selectedDate=event.target.value;shell();}}if(event.target.id==='food-complete'){const id=`checkin-${selectedDate}`,existing=store.state.records[id];await store.save({id,type:'checkin',date:selectedDate,data:{foodComplete:event.target.checked,recoveryDone:false,...existing?.data,foodComplete:event.target.checked},deleted:false,updatedAt:new Date().toISOString()});}if(event.target.id==='import-file'&&event.target.files[0]){await importBackup(event.target.files[0]);event.target.value='';}}catch(e){toast(e.message);}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('online',()=>store?.sync());window.addEventListener('offline',()=>{if(store){store.status='offline';store.changed();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)store?.sync();});

async function boot(){
  let error;
  try{const response=await fetch('/api/session',{cache:'no-store',credentials:'same-origin',signal:AbortSignal.timeout(12000),redirect:'error'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Sign in to continue.');session=data;localStorage.setItem('gym-buddy-last-account',JSON.stringify({email:data.email,local:data.local}));}
  catch(e){error=e;const last=localStorage.getItem('gym-buddy-last-account');if(!navigator.onLine&&last){try{session=JSON.parse(last);}catch{}}}
  if(!session){$('#app').innerHTML=`<main class="panel setup-gate"><div class="brand-mark">g<span>•</span></div><h1>Your private tracker.<br>Ready when you are.</h1><p>${escape(error?.message||'Connect your private sign-in to start.')}</p><div class="note">Cloudflare Pages hosts the app. D1 stores your records, and Cloudflare Access protects your sign-in. See the deployment guide to connect them.</div><div class="button-group mt">${button('Try again','reload','primary','sync')}<a class="btn" href="/signin">Private sign-in</a></div></main>`;document.querySelector('[data-action="reload"]').onclick=()=>location.reload();return;}
  try{store=await new DataStore(session.email).open();store.addEventListener('change',()=>{if(!$('#entry-dialog').open)shell();else if($('#sync-status'))$('#sync-status').innerHTML=statusHTML();});shell();await store.sync();}
  catch(e){$('#app').innerHTML=`<main class="panel setup-gate"><h1>Device storage needs attention</h1><p>${escape(e.message)}</p><p>Enable browser storage or try a regular browser window before entering health data.</p></main>`;}
  setInterval(()=>{if(!document.hidden)store?.sync();},30000);
}
if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').then(reg=>{if(reg.waiting){updateWaiting=reg.waiting;if(store)shell();}reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){updateWaiting=worker;if(store&&!$('#entry-dialog').open)shell();}});});}).catch(()=>{});}
void boot();

function projectionPanel(){const p=profile();return `<section class="panel full"><div class="panel-head"><h2>Explore a body-composition scenario</h2>${icon('weight')}</div><p class="small muted mb">An illustration of weight at a lower body-fat percentage, assuming fat-free mass stays constant. Use weight and body-fat values from the same scan. This is not a prescribed goal or a forecast.</p><div class="form-grid">${field('modelWeight','Weight from scan · kg',p.initialWeight,{type:'number',min:30,max:350,step:.01})}${field('modelFat','Body fat from same scan · %',p.bodyFat,{type:'number',min:3,max:65,step:.1})}${field('modelTarget','Illustrative body-fat target · %',25,{type:'number',min:10,max:60,step:.1})}<div class="field"><label>&nbsp;</label>${button('Explore scenario','project-composition','','chart')}</div></div><div id="composition-result"></div><div class="panel-foot">Fat-free mass includes bone, water, organs and muscle. Actual muscle gain or loss, hydration and measurement error change the result.</div></section>`;}
function projectComposition(){const result=compositionProjection(Number($('#field-modelWeight').value),Number($('#field-modelFat').value),Number($('#field-modelTarget').value));$('#composition-result').innerHTML=result?`<div class="calculator-result"><div><strong>${n(result.fatFree,1)} kg</strong><span>Estimated fat-free mass</span></div><div><strong>${n(result.targetWeight,1)} kg</strong><span>Illustrative total weight</span></div><div><strong>${n(result.weightChange,1)} kg</strong><span>Difference from scan weight</span></div></div>`:'<div class="note warn mt">Enter valid scan values and a body-fat target lower than the scan result (at least 10%).</div>';}
